html:
{% set party_label = "Supplier" if doc.payment_type == "Pay" else "Customer" %}
{% set previous_balance = abs(doc.party_balance) if doc.payment_type == "Pay" else doc.party_balance %}
{% set due_balance = abs(doc.party_balance + doc.paid_amount) if doc.payment_type == "Pay" else (doc.party_balance - doc.paid_amount) %}

<style>
    * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
        font-family: Arial, Helvetica, sans-serif;
    }

    body {
        font-size: 12px;
        color: #000;
        background: #fff;
    }

    .print-wrapper {
        width: 100%;
        padding: 8px 18px;
    }

    /* ── BRAND HEADER ── */
    .brand-header {
        text-align: center;
        margin-bottom: 8px;
    }

    /* ── DIVIDER BARS ── */
    .header-divider {
        display: flex;
        height: 4px;
        margin-bottom: 16px;
        gap: 3px;
    }
    .bar-navy    { background: #10194f; flex: 5; border-radius: 1px; }
    .bar-orange  { background: #e36c12; flex: 1; border-radius: 1px; }
    .bar-navy2   { background: #10194f; flex: 1; border-radius: 1px; }
    .bar-orange2 { background: #e36c12; flex: 3; border-radius: 1px; }

    /* ── DOCUMENT TITLE ── */
    .doc-title {
        text-align: center;
        color: #10194f;
        font-size: 20px;
        font-weight: bold;
        text-transform: uppercase;
        letter-spacing: 4px;
        margin-bottom: 4px;
    }

    .doc-subtitle {
        text-align: center;
        font-size: 12px;
        color: #e36c12;
        font-weight: bold;
        letter-spacing: 1px;
        margin-bottom: 4px;
        text-transform: uppercase;
    }

    .title-orange-line {
        width: 120px;
        height: 3px;
        background: #e36c12;
        margin: 0 auto 14px;
        border-radius: 3px;
    }

    /* ── DOC NAME ── */
    .doc-name {
        font-size: 11px;
        color: #777;
        margin-bottom: 14px;
        padding-bottom: 8px;
        border-bottom: 1px solid #dde3ee;
        text-align: center;
    }

    /* ── SUMMARY CARD (grid) ── */
    .summary-card {
        border: 2px solid #10194f;
        border-top: 4px solid #e36c12;
        border-radius: 9px;
        background: #f7f8fb;
        padding: 14px 18px;
        margin-bottom: 20px;
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0 30px;
    }

    .detail-row {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        padding: 7px 0;
        border-bottom: 1px solid #dde3ee;
        gap: 8px;
    }

    .detail-row:last-child {
        border-bottom: none;
    }

    .detail-label {
        font-size: 10px;
        font-weight: bold;
        color: #10194f;
        text-transform: uppercase;
        letter-spacing: 0.4px;
        flex-shrink: 0;
    }

    .detail-value {
        font-size: 11.5px;
        color: #000;
        text-align: right;
    }

    /* ── PAID AMOUNT HIGHLIGHT ── */
    .paid-highlight {
        grid-column: 1 / -1;
        display: flex;
        justify-content: space-between;
        align-items: center;
        background: #10194f;
        border-radius: 5px;
        padding: 9px 14px;
        margin-top: 6px;
    }

    .paid-highlight .detail-label {
        color: #fff;
        font-size: 11px;
    }

    .paid-highlight .detail-value {
        color: #e36c12;
        font-size: 15px;
        font-weight: bold;
    }

    /* ── REFERENCES TABLE ── */
    .items-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10.5px;
        margin-bottom: 20px;
    }

    .items-table thead tr {
        background-color: #10194f;
        color: #fff;
    }

    .items-table thead th {
        padding: 8px 10px;
        font-size: 10px;
        font-weight: bold;
        text-transform: uppercase;
        letter-spacing: 0.4px;
        border: 1px solid #fff;
        text-align: center;
        color: #fff !important;
    }

    .items-table thead th:first-child { border-left: 1px solid #10194f; }
    .items-table thead th:last-child  { border-right: 1px solid #10194f; }
    .items-table thead th.left        { text-align: left; }

    .items-table tbody tr:nth-child(even) { background: #f7f8fb; }
    .items-table tbody tr:nth-child(odd)  { background: #fff; }

    .items-table tbody td {
        padding: 7px 10px;
        border: 1px solid #bbc5d8;
        text-align: center;
        color: #000;
    }

    .items-table tbody td.left { text-align: left; }

    /* ── CHEQUE / REF SECTION ── */
    .ref-card {
        border: 1.5px solid #10194f;
        border-radius: 6px;
        overflow: hidden;
        margin-bottom: 24px;
    }

    .ref-card-header {
        background: #10194f;
        color: #fff;
        font-size: 10px;
        font-weight: bold;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        padding: 6px 14px;
    }

    .ref-card-body {
        background: #f7f8fb;
        border-top: 3px solid #e36c12;
        display: flex;
        gap: 0;
    }

    .ref-cell {
        flex: 1;
        padding: 10px 14px;
        border-right: 1px solid #dde3ee;
    }

    .ref-cell:last-child { border-right: none; }

    .ref-cell .rlabel {
        font-size: 9.5px;
        font-weight: bold;
        color: #10194f;
        text-transform: uppercase;
        letter-spacing: 0.4px;
        margin-bottom: 4px;
    }

    .ref-cell .rvalue {
        font-size: 12px;
        font-weight: bold;
        color: #000;
    }

    /* ── SIGNATURES ── */
    .signature-section {
        display: flex;
        justify-content: space-between;
        margin-top: 44px;
        gap: 16px;
    }

    .signature-box {
        flex: 1;
        text-align: center;
    }

    .signature-line {
        border-top: 1.5px solid #10194f;
        padding-top: 6px;
        font-size: 10.5px;
        font-weight: bold;
        color: #10194f;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        margin-top: 40px;
    }

    @media print {
        .print-wrapper { padding: 5px 14px; }
        .items-table thead tr,
        .paid-highlight,
        .ref-card-header {
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
        }
    }
</style>

<div class="print-wrapper">

    <!-- ── LETTERHEAD ── -->
    <div class="brand-header">
        {% if letter_head and not no_letterhead %}
        {{ letter_head }}
        {% endif %}
    </div>

    <!-- ── DIVIDER BARS ── -->
    <!--<div class="header-divider">-->
    <!--    <div class="bar-navy"></div>-->
    <!--    <div class="bar-orange"></div>-->
    <!--    <div class="bar-navy2"></div>-->
    <!--    <div class="bar-orange2"></div>-->
    <!--</div>-->

    <!-- ── TITLE ── -->
    <div class="doc-title">Payment Entry</div>
    <div class="doc-subtitle">{{ doc.payment_type }}</div>
    <div class="title-orange-line"></div>

    <!-- ── DOC NAME ── -->
    <div class="doc-name">{{ doc.name }}</div>

    <!-- ── SUMMARY CARD ── -->
    <div class="summary-card">

        <div class="detail-row">
            <div class="detail-label">Date</div>
            <div class="detail-value">{{ frappe.format(doc.posting_date, {'fieldtype': 'Date'}) }}</div>
        </div>

        <div class="detail-row">
            <div class="detail-label">{{ doc.party_type }}</div>
            <div class="detail-value">{{ doc.party }}</div>
        </div>

        <div class="detail-row">
            <div class="detail-label">Previous Balance</div>
            <div class="detail-value">${{ "%.2f"|format(previous_balance) }}</div>
        </div>

        <div class="detail-row">
            <div class="detail-label">Due Balance</div>
            <div class="detail-value">${{ "%.2f"|format(due_balance) }}</div>
        </div>

        <!-- Paid Amount full-width highlight -->
        <div class="paid-highlight">
            <div class="detail-label">Paid Amount</div>
            <div class="detail-value">${{ "%.2f"|format(doc.paid_amount) }}</div>
        </div>

    </div>

    <!-- ── REFERENCES TABLE ── -->
    <table class="items-table">
        <thead>
            <tr>
                <th style="width: 40px;">SR</th>
                <th class="left">Type</th>
                <th class="left">Reference</th>
                <th style="width: 120px;">Outstanding</th>
                <th style="width: 120px;">Allocated</th>
            </tr>
        </thead>
        <tbody>
            {% for ref in doc.references %}
            <tr>
                <td>{{ loop.index }}</td>
                <td class="left">{{ ref.reference_doctype or ""}}</td>
                <td class="left">{{ ref.reference_name or ""}}</td>
                <td>—</td>
                <td>${{ "{:,.2f}".format(ref.allocated_amount or "") }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- ── CHEQUE / REFERENCE ── -->
    <div class="ref-card">
        <div class="ref-card-header">Cheque / Reference Details</div>
        <div class="ref-card-body">
            <div class="ref-cell">
                <div class="rlabel">Cheque / Reference No.</div>
                <div class="rvalue">{{ doc.reference_no or "—" }}</div>
            </div>
            <div class="ref-cell">
                <div class="rlabel">Reference Date</div>
                <div class="rvalue">{{ doc.reference_date or "—" }}</div>
            </div>
            <div class="ref-cell">
                <div class="rlabel">Mode of Payment</div>
                <div class="rvalue">{{ doc.mode_of_payment or "—" }}</div>
            </div>
        </div>
    </div>

    <!-- ── SIGNATURES ── -->
    <div class="signature-section">
         {%if doc.payment_type == "Pay" %}
        <div class="signature-box">
            <div class="signature-line">Prepared By Accountant</div>
        </div>
        {% else %}
         
        <div class="signature-box">
            <div class="signature-line">Received By cashier</div>
        </div>
     
        {% endif %}
        <div class="signature-box">
            <div class="signature-line"> Checked By Finance Office</div>
        </div>
        {%if doc.payment_type == "Pay" %}
        <div class="signature-box">
            <div class="signature-line">Approved By Director</div>
        </div>
        {% else %}
           <div class="signature-box">
            <div class="signature-line">Checked By Accountant</div>
        </div>
     
        {% endif %}
        
        
    </div>

</div>
